import { BlockControls, HeadingLevelDropdown, useBlockProps } from '@wordpress/block-editor';
import { registerBlockType } from '@wordpress/blocks';
import { Spinner } from '@wordpress/components';
import { useSelect } from '@wordpress/data';

const Edit = ({ attributes, setAttributes }) => {
	const { textAlign, level } = attributes;

	const TagName = 'h' + level;

	const { termDisplayTitle, isLoading } = useSelect((select) => {
		const { getEntityRecord } = select('core');
		
		const urlParams = new URLSearchParams(window.location.search);
		const termId = urlParams.get('taxonomy') || urlParams.get('tag_ID');
		
		if (termId) {
			const taxonomies = ['category', 'post_tag', 'product_cat'];
			
			for (const taxonomy of taxonomies) {
				const term = getEntityRecord('taxonomy', taxonomy, termId);
				
				if (term) {
					const title = term.acf?.term_display_title || term.meta?.term_display_title;
					
					return {
						termDisplayTitle: title,
						isLoading: false,
					};
				}
			}
		}

		return { termDisplayTitle: null, isLoading: false };
	}, []);

	const blockProps = useBlockProps({
		className: textAlign ? `has-text-align-${textAlign}` : undefined,
	});

	if (isLoading) {
		return (
			<>
				<BlockControls group="block">
					<HeadingLevelDropdown
						value={level}
						onChange={(newLevel) => setAttributes({ level: newLevel })}
					/>
				</BlockControls>
				<div {...blockProps}>
					<TagName><Spinner /></TagName>
				</div>
			</>
		);
	}

	if (!termDisplayTitle) {
		return (
			<>
				<BlockControls group="block">
					<HeadingLevelDropdown
						value={level}
						onChange={(newLevel) => setAttributes({ level: newLevel })}
					/>
				</BlockControls>
				<div {...blockProps}>
					<TagName>{attributes.placeholder || 'Term Display Title'}</TagName>
				</div>
			</>
		);
	}

	return (
		<>
			<BlockControls group="block">
				<HeadingLevelDropdown
					value={level}
					onChange={(newLevel) => setAttributes({ level: newLevel })}
				/>
			</BlockControls>
			<TagName {...blockProps}>
				{termDisplayTitle}
			</TagName>
		</>
	);
};

registerBlockType('mellobase/term-display-title', {
    edit: Edit,
    save: () => {
        return null; // Dynamic block, rendered in PHP
    }
});

export default Edit;